# NEXA News and Media Engine Phase 12 Test Script

Set-Location $PSScriptRoot

python -c "from media_engine import MediaEngine; engine = MediaEngine(); event = {'id': 'protest_001', 'type': 'police_disperse_protest', 'description': 'Police dispersed a protest in City Square after tensions escalated.'}; reports = engine.process_event(event, simulation_day=18); print('NEXA Phase 12 News and Media Test'); print(); print(f'Event processed: {event['description']}'); print(); print('FICTIONAL MEDIA COVERAGE:'); [print(f'[{report.organization_name} | {report.alignment.value}]\\nHEADLINE: {report.headline}\\nBROADCAST: {report.broadcast}\\nARTICLE: {report.article}\\nBIAS NOTE: {report.bias_notes}\\n') for report in reports if report.content_type.value == 'article']; print('RUMOURS (UNVERIFIED):'); [print(f'[{report.alignment.value}] {report.rumour}') for report in reports if report.content_type.value == 'rumour']; print(); print('SOCIAL REACTIONS:'); [print(f'[{report.alignment.value}] {report.social_reaction}') for report in reports if report.content_type.value == 'social_reaction']; print(); print('NIA MEDIA CONTEXT:'); [print(f'[{report['organization_name']}] {report['headline'] or report['rumour'] or report['social_reaction']}') for report in engine.get_nia_media_context(event_id='protest_001')]; print(); print('PASS: One event generated multiple competing reports, rumours and public reactions.')"
